import re
from collections import deque

LINE_RE = re.compile(r"^(\w+)=(.*)$")


def drain(tasks, handle):
    while tasks:
        task = tasks.pop(0)
        handle(task)


def drain_fast(tasks, handle):
    queue = deque(tasks)
    while queue:
        handle(queue.popleft())


def prepend_all(items):
    result = []
    for item in items:
        result.insert(0, item)
    return result


def parse_lines(lines):
    parsed = []
    for line in lines:
        pattern = re.compile(r"^(\w+)=(.*)$")
        match = pattern.match(line)
        if match:
            parsed.append(match.groups())
    return parsed


def parse_lines_fast(lines):
    return [m.groups() for m in map(LINE_RE.match, lines) if m]
